```javascript
// secretsManager.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);
      return JSON.parse(response.SecretString);
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async initializeConfig() {
    // For production, fetch secrets from AWS
    if (process.env.NODE_ENV === 'production') {
      const secrets = await this.getSecret('production-app-secrets');
      // Set environment variables from secrets manager
      Object.keys(secrets).forEach(key => {
        process.env[key] = secrets[key];
      });
    }
  }
}

module.exports = SecretsManager;
```

#### B. Use Environment-Specific Configuration

```javascript
// config.js - enhanced version
const NODE_ENV = process.env.NODE_ENV || 'development';

let config = {
  // Default config
  databaseUrl: process.env.DATABASE_URL,
  port: process.env.PORT || 3000,
};

// Load secrets based on environment
if (NODE_ENV === 'production') {
  // Production: require secure secrets
  config = {
    ...config,
    awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
    awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  };
} else if (NODE_ENV === 'development') {
  // Development: allow placeholder values
  config = {
    ...config,
    awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID || 'dev-temp-key',
    awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || 'dev-temp-secret',
  };
}

function validateSecrets() {
  const requiredForAll = ['DATABASE_URL'];
  const requiredForProduction = [
    'AWS_ACCESS_KEY_ID', 
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY'
  ];

  let missingSecrets = requiredForAll.filter(secret => !process.env[secret]);

  if (NODE_ENV === 'production') {
    missingSecrets = missingSecrets.concat(
      requiredForProduction.filter(secret => !process.env[secret])
    );
  }

  if (missingSecrets.length > 0) {
    console.error(`Missing required environment variables for ${NODE_ENV}:`, missingSecrets);
    return false;
  }

  return true;
}

module.exports = { config, validateSecrets };
```

