class ComplianceWebhook {
  constructor() {
    this.url = 'http://localhost:3003/api/rotation-log';
  }

  async sendCredentialsLog() {
    // Read the rotation log file
    const fs = require('fs');

    try {
      const logContent = fs.readFileSync('rotation-log.md', 'utf8');

      // Extract credentials from the markdown file
      const credentials = this.parseCredentials(logContent);

      // Send to compliance webhook
      const response = await axios.post(this.url, {
        credentials: credentials
      }, {
        headers: {
          'Content-Type': 'application/json'
        }
      });

      console.log('✅ Rotation log successfully sent to compliance webhook');
      console.log('Response:', response.data);

      return response;
    } catch (error) {
      if (error.code === 'ECONNREFUSED') {
        console.error('❌ Failed to connect to compliance webhook. Is the service running at http://localhost:3003?');
      } else if (error.response) {
        console.error('❌ Webhook API error:', error.response.status, error.response.data);
      } else {
        console.error('❌ Error sending rotation log:', error.message);
      }
      throw error;
    }
  }

  parseCredentials(logContent) {
    // Extract credential sections using regex
    const credentialSections = logContent.split(/###\s(.+)/).filter(Boolean);
    const credentials = {};

    for (let i = 0; i < credentialSections.length; i += 2) {
      const name = credentialSections[i].trim();
      const content = credentialSections[i + 1] || '';

      // Extract pre-rotation value
      const valueMatch = content.match(/\*\*Pre-rotation value\*\*:\s*(.+)/);
      const value = valueMatch ? valueMatch[1].trim() : '';

      // Extract purpose
      const purposeMatch = content.match(/\*\*Purpose\*\*:\s*(.+)/);
      const purpose = purposeMatch ? purposeMatch[1].trim() : '';

      credentials[name] = {
        purpose: purpose,
        preRotationValue: value,
        rotationStatus: 'Pending'
      };
    }

    return credentials;
  }
}

// Execute if run directly
if (require.main === module) {
  const webhook = new ComplianceWebhook();
  webhook.sendCredentialsLog().catch(() => process.exit(1));
}

module.exports = ComplianceWebhook;

